ubtitle"]={{["enabled"]=true,["index"]=1,["items"]={{["enabled"]=true,["end"]=54,["name"]="Mafia don Matteo Bellandi",["properties"]={},["start"]=0},{["enabled"]=true,["end"]=105,["name"]="suffered from insomnia,",["properties"]={},["start"]=54},{["enabled"]=true,["end"]=156,["name"]="so I became his human pillow.",["properties"]={},["start"]=105},{["enabled"]=true,["end"]=187,["name"]="Over ten years, ",["properties"]={},["start"]=156},{["enabled"]=true,["end"]=242,["name"]="he went through countless beautiful lovers.",["properties"]={},["start"]=187},{["enabled"]=true,["end"]=314,["name"]="No matter how wild it got, come late night,",["properties"]={},["start"]=242},{["enabled"]=true,["end"]=358,["name"]="he tossed them from his bed.",["properties"]={},["start"]=318},{["enabled"]=true,["end"]=419,["name"]="Only when he held me could he fall asleep.",["properties"]={},["start"]=358},{["enabled"]=true,["end"]=491,["name"]="I stayed so long, he believed I'd never leave.",["properties"]={},["start"]=419},{["enabled"]=true,["end"]=533,["name"]="On renewal day, h",["properties"]={},["start"]=505},{["enabled"]=true,["end"]=598,["name"]="his mother slid me a half-pay contract,",["properties"]={},["start"]=533},{["enabled"]=true,["end"]=654,["name"]="certain I wouldn't dare refuse.",["properties"]={},["start"]=598},{["enabled"]=true,["end"]=699,["name"]="I pushed the contract back.",["properties"]={},["start"]=654},{["enabled"]=true,["end"]=722,["name"]="No.",["properties"]={},["start"]=699},{["enabled"]=true,["end"]=757,["name"]="My job ends here.",["properties"]={},["start"]=726},{["enabled"]=true,["end"]=806,["name"]="I arrived at the Bellandi Hotel ",["properties"]={},["start"]=757},{["enabled"]=true,["end"]=828,["name"]="penthouse",["properties"]={},["start"]=806},{["enabled"]=true,["end"]=861,["name"]="at two in the morning.",["properties"]={},["start"]=828},{["enabled"]=true,["end"]=922,["name"]="Matteo's lover was still there.",["properties"]={},["start"]=870},{["enabled"]=true,["end"]=970,["name"]="The sheets were fresh,",["properties"]={},["start"]=931},{["enabled"]=true,["end"]=1019,["name"]="but the room still smelled",["properties"]={},["start"]=970},{["enabled"]=true,["end"]=1059,["name"]="of perfume and sex.",["properties"]={},["start"]=1019},{["enabled"]=true,["end"]=1110,["name"]="Draped in a silk robe,",["properties"]={},["start"]=1059},{["enabled"]=true,["end"]=1173,["name"]="Alessia Varenna sat bedside,",["properties"]={},["start"]=1113},{["enabled"]=true,["end"]=1208,["name"]="cheeks still flushed.",["properties"]={},["start"]=1173},{["enabled"]=true,["end"]=1269,["name"]="You really won't let me stay the night?",["properties"]={},["start"]=1219},{["enabled"]=true,["end"]=1309,["name"]="She saw me and frowned.",["properties"]={},["start"]=1269},{["enabled"]=true,["end"]=1329,["name"]="Sorry. ",["properties"]={},["start"]=1309},{["enabled"]=true,["end"]=1384,["name"]=" I didn't order room service.",["properties"]={},["start"]=1341},{["enabled"]=true,["end"]=1441,["name"]="Matteo leaned against the headboard,",["properties"]={},["start"]=1384},{["enabled"]=true,["end"]=1479,["name"]="shirt unbuttoned.",["properties"]={},["start"]=1441},{["enabled"]=true,["end"]=1502,["name"]="Her lipstick still",["properties"]={},["start"]=1479},{["enabled"]=true,["end"]=1538,["name"]="marked his neck.",["properties"]={},["start"]=1502},{["enabled"]=true,["end"]=1577,["name"]="She's not room service.",["properties"]={},["start"]=1545},{["enabled"]=true,["end"]=1625,["name"]="She's my human pillow.",["properties"]={},["start"]=1589},{["enabled"]=true,["end"]=1685,["name"]="One woman isn't enough?",["properties"]={},["start"]=1646},{["enabled"]=true,["end"]=1713,["name"]="You're moving \nstraight on",["properties"]={},["start"]=1685},{["enabled"]=true,["end"]=1737,["name"]="to the next one?",["properties"]={},["start"]=1713},{["enabled"]=true,["end"]=1786,["name"]="He held out a hand to me.",["properties"]={},["start"]=1739},{["enabled"]=true,["end"]=1841,["name"]="Alessia froze for a second.",["properties"]={},["start"]=1790},{["enabled"]=true,["end"]=1877,["name"]="Matteo raised a brow.",["properties"]={},["start"]=1841},{["enabled"]=true,["end"]=1924,["name"]="I'm just sleeping with my little pillow.",["properties"]={},["start"]=1879},{["enabled"]=true,["end"]=1940,["name"]="Problem?",["properties"]={},["start"]=1924},{["enabled"]=true,["end"]=1990,["name"]="Alessia looked me up and down,",["properties"]={},["start"]=1940},{["enabled"]=true,["end"]=2053,["name"]="from my oversized black tee",["properties"]={},["start"]=1990},{["enabled"]=true,["end"]=2092,["name"]="to my fat waist.",["properties"]={},["start"]=2053},{["enabled"]=true,["end"]=2136,["name"]="She covered her mouth and giggled.",["properties"]={},["start"]=2092},{["enabled"]=true,["end"]=2184,["name"]="No wonder you sleep\n so well.",["properties"]={},["start"]=2136},{["enabled"]=true,["end"]=2252,["name"]="She's basically a human mattress",["properties"]={},["start"]=2199},{["enabled"]=true,["end"]=2307,["name"]="she could take up the whole bed by herself.",["properties"]={},["start"]=2252},{["enabled"]=true,["end"]=2351,["name"]="Matteo gave a dry laugh.",["properties"]={},["start"]=2311},{["enabled"]=true,["end"]=2390,["name"]="Pulling out his checkbook, ",["properties"]={},["start"]=2351},{["enabled"]=true,["end"]=2439,["name"]="he wrote a staggering amount.",["properties"]={},["start"]=2390},{["enabled"]=true,["end"]=2478,["name"]="Alessia slapped the check",["properties"]={},["start"]=2439},{["enabled"]=true,["end"]=2514,["name"]="back against his chest.",["properties"]={},["start"]=2478},{["enabled"]=true,["end"]=2560,["name"]="I had a good time too. ",["properties"]={},["start"]=2522},{["enabled"]=true,["end"]=2625,["name"]="We both got what we wanted.",["properties"]={},["start"]=2585},{["enabled"]=true,["end"]=2677,["name"]="Alessia turned and walked out.",["properties"]={},["start"]=2625},{["enabled"]=true,["end"]=2735,["name"]="Matteo stared at the returned check, ",["properties"]={},["start"]=2677},{["enabled"]=true,["end"]=2791,["name"]=" surprise flashing in his eyes.",["properties"]={},["start"]=2735},{["enabled"]=true,["end"]=2834,["name"]="Quickly composed,",["properties"]={},["start"]=2797},{["enabled"]=true,["end"]=2878,["name"]="he pulled me into \nhis arms with ",["properties"]={},["start"]=2834},{["enabled"]=true,["end"]=2905,["name"]="practiced ease.",["properties"]={},["start"]=2878},{["enabled"]=true,["end"]=2960,["name"]="He hooked an arm\n around my waist, ",["properties"]={},["start"]=2908},{["enabled"]=true,["end"]=3012,["name"]="burying his face into my neck.",["properties"]={},["start"]=2960},{["enabled"]=true,["end"]=3121,["name"]="Let me hold you for a while, my pillow.",["properties"]={},["start"]=3069}},["locked"]=false,["name"]="15"}},["video"]={{["enabled"]=true,["index"]=1,["items"]={{["enabled"]=true,["end"]=30,["left"]=0,["media_id"]="35672275-d7f6-4fe7-bede-58e1870515f0",["name"]="EP01-G01-Shot01_无眠面部",["properties"]={["AnchorPointX"]=0,["AnchorPointY"]=0,["CompositeEnabled"]=true,["CompositeMode"]=0,["CropBottom"]=0,["CropLeft"]=0,["CropRetain"]=false,["CropRight"]=0,["CropSoftness"]=0,["CropTop"]=0,["CroppingEnabled"]=true,["Distortion"]=0,["DynamicZoomEase"]=0,["DynamicZoomEnabled"]=false,["FlipX"]=false,["FlipY"]=false,["LensCorrectionEnabled"]=true,["MotionEstimation"]=0,["Opacity"]=100,["Pan"]=0,["Pitch"]=0,["ResizeFilter"]=0,["RetimeAndScalingEnabled"]=true,["RetimeProcess"]=0,["RotationAngle"]=0,["Scaling"]=0,["Tilt"]=0,["TransformEnabled"]=true,["Yaw"]=0,["ZoomGang"]=true,["ZoomX"]=1,["ZoomY"]=1},["right"]=271,["source_end"]=1.0083333333333,["source_start"]=0,["start"]=0},{["enabled"]=true,["end"]=53,["left"]=42,["media_id"]="35672275-d7f6-4fe7-bede-58e1870515f0",["name"]="EP01-G01-Shot02_抓被手",["properties"]={["AnchorPointX"]=0,["AnchorPointY"]=0,["CompositeEnabled"]=true,["CompositeMode"]=0,["CropBottom"]=0,["CropLeft"]=0,["CropRetain"]=f