=true,["index"]=1,["items"]={{["enabled"]=true,["end"]=543,["name"]="Her perfume still lingered in the room.",["properties"]={},["start"]=492},{["enabled"]=true,["end"]=640,["name"]="I looked down and saw the lipstick mark on Matteo's neck,",["properties"]={},["start"]=550},{["enabled"]=true,["end"]=746,["name"]="bright and glaring, like a mark staking a claim.",["properties"]={},["start"]=650},{["enabled"]=true,["end"]=824,["name"]="Matteo seemed to be in a good mood tonight.",["properties"]={},["start"]=772},{["enabled"]=true,["end"]=862,["name"]="I didn't answer.",["properties"]={},["start"]=831},{["enabled"]=true,["end"]=925,["name"]="After a moment, he said.",["properties"]={},["start"]=869},{["enabled"]=true,["end"]=967,["name"]="That surprised me.",["properties"]={},["start"]=929},{["enabled"]=true,["end"]=1026,["name"]="In ten years of sharing a bed,",["properties"]={},["start"]=971},{["enabled"]=true,["end"]=1127,["name"]="he'd never spent a night outside his security perimeter.",["properties"]={},["start"]=1028},{["enabled"]=true,["end"]=1185,["name"]="Yet, half an hour later,",["properties"]={},["start"]=1137},{["enabled"]=true,["end"]=1275,["name"]="a Bellandi car stopped outside my apartment building.",["properties"]={},["start"]=1199},{["enabled"]=true,["end"]=1348,["name"]="Matteo changed into his black pajamas",["properties"]={},["start"]=1286},{["enabled"]=true,["end"]=1426,["name"]="and lay straight on my small pale bed.",["properties"]={},["start"]=1348},{["enabled"]=true,["end"]=1492,["name"]="He looked wildly out of place",["properties"]={},["start"]=1433},{["enabled"]=true,["end"]=1591,["name"]="among my pale pink sheets, plush pillows, and plushies.",["properties"]={},["start"]=1492},{["enabled"]=true,["end"]=1678,["name"]="He turned on his side and pulled me tight against him.",["properties"]={},["start"]=1593},{["enabled"]=true,["end"]=1800,["name"]="His hand pressed into my soft belly, his long legs trapping mine.",["properties"]={},["start"]=1680},{["enabled"]=true,["end"]=1929,["name"]="I mumbled, already half asleep, but Matteo was wide awake.",["properties"]={},["start"]=1805},{["enabled"]=true,["end"]=2035,["name"]="His nose traced down my hair and stopped at my neck.",["properties"]={},["start"]=1938},{["enabled"]=true,["end"]=2137,["name"]="His lips barely brushed the sensitive skin there.",["properties"]={},["start"]=2043},{["enabled"]=true,["end"]=2251,["name"]="I clenched the hem of my pajama top, my breath catching.",["properties"]={},["start"]=2144},{["enabled"]=true,["end"]=2322,["name"]="His hot breath brushed my skin.",["properties"]={},["start"]=2262},{["enabled"]=true,["end"]=2446,["name"]="I jerked my head up and my lips accidentally brushed his chin.",["properties"]={},["start"]=2330},{["enabled"]=true,["end"]=2482,["name"]="We both froze.",["properties"]={},["start"]=2449}},["locked"]=false,["name"]="15"}},["video"]={{["enabled"]=true,["index"]=1,["items"]={{["enabled"]=true,["end"]=6187,["left"]=0,["media_id"]="15036328-f5db-4728-9314-3d1acfdebf66",["name"]="EP02.mp4",["properties"]={["AnchorPointX"]=0,["AnchorPointY"]=0,["CompositeEnabled"]=true,["CompositeMode"]=0,["CropBottom"]=0,["CropLeft"]=0,["CropRetain"]=false,["CropRight"]=0,["CropSoftness"]=0,["CropTop"]=0,["CroppingEnabled"]=true,["Distortion"]=0,["DynamicZoomEase"]=0,["DynamicZoomEnabled"]=false,["FlipX"]=false,["FlipY"]=false,["LensCorrectionEnabled"]=true,["MotionEstimation"]=0,["Opacity"]=100,["Pan"]=0,["Pitch"]=0,["ResizeFilter"]=0,["RetimeAndScalingEnabled"]=true,["RetimeProcess"]=0,["RotationAngle"]=0,["Scaling"]=0,["Tilt"]=0,["TransformEnabled"]=true,["Yaw"]=0,["ZoomGang"]=true,["ZoomX"]=1,["ZoomY"]=1},["right"]=0,["source_end"]=75.073333333333,["source_start"]=0,["start"]=3935}},["locked"]=false,["name"]="视频 1"},{["enabled"]=true,["index"]=2,["items"]={},["locked"]=false,["name"]="视频 2"},{["enabled"]=true,["index"]=3,["items"]={},["locked"]=false,["name"]="视频 3"},{["enabled"]=true,["index"]=4,["items"]={},["loc